<?php $title='Features'; ?>
<div class="page-head"><div><span class="eyebrow">FEATURE MANAGEMENT</span><h1>Features</h1><p><?= $isTestEnvironment?'Bản nháp':'Trạng thái đang phát hành' ?> v<?= (int)($draft['version_number'] ?? 0) ?> · <?= e($environment['name']) ?>. Mọi tính năng được chọn từ thư viện do Admin quản lý.</p></div><a class="button" href="<?= e(url('versions')) ?>">Lịch sử phiên bản</a></div>
<?php if(!$isTestEnvironment): ?><div class="notice info">Môi trường phát hành đang ở chế độ chỉ xem. Hãy chuyển sang Staging để thay đổi cấu hình.</div><?php endif; ?>
<section class="panel"><div class="panel-head"><div><h2>Features trong dự án</h2><p><?= $isTestEnvironment?'Thay đổi được lưu vào bản nháp Staging; chỉ bản nháp của môi trường này có thể chỉnh sửa.':'Trạng thái dưới đây là cấu hình đang phát hành.' ?></p></div><?php if($draft): ?><span class="pill <?= $draft['status']==='draft'?'amber':'green' ?>"><?= e(strtoupper($draft['status'])) ?> v<?= (int)$draft['version_number'] ?></span><?php endif; ?></div><?php if(!$flags): ?><p class="empty">Dự án chưa dùng tính năng nào từ thư viện Admin.</p><?php else: ?><div class="feature-list"><?php foreach($flags as $flag): $isEnabled=(bool)$flag['kill_switch']?false:($flag['forced_value']!==null?(bool)$flag['forced_value']:((bool)$flag['default_value'] || ((bool)$flag['rollout_enabled'] && (float)$flag['rollout_percentage']>0))); ?><form method="post" action="<?= e(url('flags/update')) ?>" class="feature-row"><?= csrf_field() ?><input type="hidden" name="flag_id" value="<?= (int)$flag['id'] ?>"><div class="feature-info"><strong><?= e($flag['name']) ?></strong><code><?= e($flag['key']) ?></code><small><?= e($flag['description']) ?></small></div><span class="pill <?= $isEnabled?'green':'gray' ?>"><?= $isEnabled?'ĐANG BẬT':'ĐANG TẮT' ?></span><?php if($flag['can_edit']): ?><label class="check-label"><input type="checkbox" name="default_value" value="1" <?= !empty($flag['default_value'])?'checked':'' ?>> Default bật</label><label class="check-label"><input type="checkbox" name="kill_switch" value="1" <?= !empty($flag['kill_switch'])?'checked':'' ?>> Kill switch</label><label class="check-label"><input type="checkbox" name="rollout_enabled" value="1" <?= !empty($flag['rollout_enabled'])?'checked':'' ?>> Rollout</label><label class="field-inline">Tỷ lệ %<input type="number" name="rollout_percentage" min="0" max="100" step="0.1" value="<?= e($flag['rollout_percentage'] ?? 0) ?>"></label><label class="check-label"><input type="checkbox" name="fallback_value" value="1" <?= !empty($flag['fallback_value'])?'checked':'' ?>> Fallback</label><label class="field-inline">Lý do<input name="reason" placeholder="Lý do thay đổi"></label><button class="button primary" type="submit">Lưu nháp</button><?php if(($user['account_type']??'')==='owner' && App\Support\Auth::isAdmin($projectId)): ?><button class="button" type="submit" formaction="<?= e(url('flags/toggle')) ?>" name="enabled" value="<?= $isEnabled?'0':'1' ?>"><?= $isEnabled?'Tắt trong nháp':'Bật trong nháp' ?></button><?php endif; ?><?php else: ?><span class="pill gray">Chỉ xem</span><?php endif; ?></form><?php endforeach; ?></div><?php endif; ?></section>
<?php if($isTestEnvironment && ($user['account_type']??'')==='owner' && App\Support\Auth::isAdmin($projectId)): ?><section class="panel"><div class="panel-head"><div><h2>Thêm tính năng có sẵn vào bản nháp</h2><p>Chọn tính năng do Admin cung cấp; thay đổi chỉ nằm trong Staging cho đến khi phát hành.</p></div></div><?php if(!$availableCatalogFeatures): ?><p class="empty">Dự án đã có toàn bộ tính năng đang được cung cấp trong thư viện.</p><?php else: ?><form method="post" action="<?= e(url('flags/add-from-catalog')) ?>" class="inline-form"><?= csrf_field() ?><select name="catalog_feature_id" required><option value="">Chọn tính năng</option><?php foreach($availableCatalogFeatures as $feature): ?><option value="<?= (int)$feature['id'] ?>"><?= e($feature['name']) ?> · <?= e($feature['key']) ?></option><?php endforeach; ?></select><button class="button primary" type="submit">Thêm vào bản nháp</button></form><?php endif; ?></section><?php endif; ?>
